-- Research Assist Lane v1 (Phase 1 - Shadow Mode)
-- Adds research_brief JSONB column to work_items for storing AI-generated scope enrichment briefs.
-- The brief is generated for ambiguous jobs and stored here for audit and UI display.
-- It does not affect pricing in Phase 1.

alter table work_items
  add column if not exists research_brief jsonb;

comment on column work_items.research_brief is
  'Structured research brief generated by the research-assistant agent for ambiguous jobs. '
  'Phase 1: stored for display and audit only. Phase 2: used to enrich estimation inputs.';
